{"yol":"telefon.js","icerik":"export function telefonNormalle(numara) {
  const rakamlar = numara.replace(/\D/g, '') // Tüm rakamları çıkar

  // Eğer +90 ile başlıyorsa, 90'ı çıkar
  if (rakamlar.startsWith('90')) {
    rakamlar = rakamlar.slice(2)
  }
  // Eğer 0 ile başlıyorsa, 0'ı çıkar
  else if (rakamlar.startsWith('0')) {
    rakamlar = rakamlar.slice(1)
  }

  return `+90${rakamlar}`
}"}

